#include <torch/extension.h>
#include <vector>

torch::Tensor gru_bidirectional_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> weight_ih_l,
    std::vector<torch::Tensor> weight_hh_l,
    std::vector<torch::Tensor> bias_ih_l,
    std::vector<torch::Tensor> bias_hh_l,
    int64_t num_layers,
    int64_t hidden_size,
    bool batch_first
);

torch::Tensor grubi_forward(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> params,
    bool batch_first
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(h0.is_cuda(), "h0 must be a CUDA tensor");
    TORCH_CHECK(h0.dtype() == torch::kFloat32, "h0 must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(h0.is_contiguous(), "h0 must be contiguous");

    int64_t num_layers = h0.size(0) / 2;
    int64_t hidden_size = h0.size(2);

    std::vector<torch::Tensor> weight_ih_l, weight_hh_l, bias_ih_l, bias_hh_l;
    for (int64_t i = 0; i < num_layers * 2; ++i) {
        weight_ih_l.push_back(params[i * 4 + 0]);
        weight_hh_l.push_back(params[i * 4 + 1]);
        bias_ih_l.push_back(params[i * 4 + 2]);
        bias_hh_l.push_back(params[i * 4 + 3]);
    }

    return gru_bidirectional_forward_cuda(
        x, h0, weight_ih_l, weight_hh_l, bias_ih_l, bias_hh_l,
        num_layers, hidden_size, batch_first
    );
}

