CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__device__ __forceinline__ float sigmoid_device(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ __forceinline__ float tanh_device(float x) {
    return tanhf(x);
}

__global__ void gru_cell_kernel(
    const float* __restrict__ x_proj,
    const float* __restrict__ h_prev,
    const float* __restrict__ weight_hh,
    const float* __restrict__ bias_hh,
    float* __restrict__ h_out,
    int64_t batch_size,
    int64_t hidden_size
) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (batch_idx >= batch_size) return;

    for (int h = 0; h < hidden_size; ++h) {
        float r_ih = x_proj[batch_idx * (3 * hidden_size) + h];
        float z_ih = x_proj[batch_idx * (3 * hidden_size) + hidden_size + h];
        float n_ih = x_proj[batch_idx * (3 * hidden_size) + 2 * hidden_size + h];

        float r_hh = bias_hh[h];
        float z_hh = bias_hh[hidden_size + h];
        float n_hh = bias_hh[2 * hidden_size + h];

        for (int k = 0; k < hidden_size; ++k) {
            float h_val = h_prev[batch_idx * hidden_size + k];
            r_hh += weight_hh[h * hidden_size + k] * h_val;
            z_hh += weight_hh[(hidden_size + h) * hidden_size + k] * h_val;
            n_hh += weight_hh[(2 * hidden_size + h) * hidden_size + k] * h_val;
        }

        float r = sigmoid_device(r_ih + r_hh);
        float z = sigmoid_device(z_ih + z_hh);
        float n = tanh_device(n_ih + r * n_hh);

        float h_new = (1.0f - z) * n + z * h_prev[batch_idx * hidden_size + h];
        h_out[batch_idx * hidden_size + h] = h_new;
    }
}

torch::Tensor gru_bidirectional_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> weight_ih_l,
    std::vector<torch::Tensor> weight_hh_l,
    std::vector<torch::Tensor> bias_ih_l,
    std::vector<torch::Tensor> bias_hh_l,
    int64_t num_layers,
    int64_t hidden_size,
    bool batch_first
) {
    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());

    if (batch_first) {
        x = x.transpose(0, 1).contiguous();
    }

    int64_t seq_len = x.size(0);
    int64_t batch_size = x.size(1);
    int64_t input_size = x.size(2);

    auto current_input = x;

    for (int64_t layer = 0; layer < num_layers; ++layer) {
        int64_t fwd_idx = layer * 2;
        int64_t bwd_idx = layer * 2 + 1;

        auto w_ih_fwd = weight_ih_l[fwd_idx];
        auto w_hh_fwd = weight_hh_l[fwd_idx];
        auto b_ih_fwd = bias_ih_l[fwd_idx];
        auto b_hh_fwd = bias_hh_l[fwd_idx];

        auto w_ih_bwd = weight_ih_l[bwd_idx];
        auto w_hh_bwd = weight_hh_l[bwd_idx];
        auto b_ih_bwd = bias_ih_l[bwd_idx];
        auto b_hh_bwd = bias_hh_l[bwd_idx];

        auto h_fwd = h0[fwd_idx];
        auto h_bwd = h0[bwd_idx];

        auto output_fwd = torch::zeros({seq_len, batch_size, hidden_size}, options);
        auto output_bwd = torch::zeros({seq_len, batch_size, hidden_size}, options);

        int threads = 256;
        int blocks = (batch_size + threads - 1) / threads;

        for (int64_t t = 0; t < seq_len; ++t) {
            auto x_t = current_input[t];
            auto x_proj_fwd = torch::addmm(b_ih_fwd, x_t, w_ih_fwd.t());

            gru_cell_kernel<<<blocks, threads>>>(
                x_proj_fwd.data_ptr<float>(),
                h_fwd.data_ptr<float>(),
                w_hh_fwd.data_ptr<float>(),
                b_hh_fwd.data_ptr<float>(),
                output_fwd[t].data_ptr<float>(),
                batch_size,
                hidden_size
            );

            h_fwd = output_fwd[t];
        }

        for (int64_t t = seq_len - 1; t >= 0; --t) {
            auto x_t = current_input[t];
            auto x_proj_bwd = torch::addmm(b_ih_bwd, x_t, w_ih_bwd.t());

            gru_cell_kernel<<<blocks, threads>>>(
                x_proj_bwd.data_ptr<float>(),
                h_bwd.data_ptr<float>(),
                w_hh_bwd.data_ptr<float>(),
                b_hh_bwd.data_ptr<float>(),
                output_bwd[t].data_ptr<float>(),
                batch_size,
                hidden_size
            );

            h_bwd = output_bwd[t];
        }

        current_input = torch::cat({output_fwd, output_bwd}, 2);
    }

    if (batch_first) {
        current_input = current_input.transpose(0, 1).contiguous();
    }

    return current_input;
}
# <<<END_IMPROVE>>>
"""

